import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"Privacy And Unlocks","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-features.md","filePath":"privacy-features.md"}'),o={name:"privacy-features.md"};function d(c,e,l,s,n,p){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="privacy-and-unlocks" tabindex="-1">Privacy And Unlocks <a class="header-anchor" href="#privacy-and-unlocks" aria-label="Permalink to &quot;Privacy And Unlocks&quot;">​</a></h1><p>Privacy is not a side feature in zkde.fi. It is the operating model.</p><h2 id="what-stays-private-vs-what-is-shared" tabindex="-1">What Stays Private Vs What Is Shared <a class="header-anchor" href="#what-stays-private-vs-what-is-shared" aria-label="Permalink to &quot;What Stays Private Vs What Is Shared&quot;">​</a></h2><p>Private by default:</p><ul><li>Strategy intent and portfolio-sensitive inputs</li><li>Private deposit/withdraw secrets and commitment material</li><li>Internal decision context used by policy and model layers</li></ul><p>Shared when needed:</p><ul><li>Proofs that a check passed</li><li>Receipts that an execution happened</li><li>Disclosure artifacts for partner/compliance workflows</li></ul><h2 id="privacy-modes-you-will-see-in-product" tabindex="-1">Privacy Modes You Will See In Product <a class="header-anchor" href="#privacy-modes-you-will-see-in-product" aria-label="Permalink to &quot;Privacy Modes You Will See In Product&quot;">​</a></h2><p>Trade and execution flows can run with different privacy levels.</p><ul><li><code>public</code>: standard transparent route</li><li><code>shielded</code>: partial privacy with proof-linked controls</li><li><code>fully_private</code>: commitment/proof-first flow with minimal disclosure</li></ul><h2 id="what-privacy-unlocks" tabindex="-1">What Privacy Unlocks <a class="header-anchor" href="#what-privacy-unlocks" aria-label="Permalink to &quot;What Privacy Unlocks&quot;">​</a></h2><ul><li>Access to sensitive strategies without exposing full intent on every step</li><li>Policy-aware automation with proof checkpoints</li><li>Better trust posture over time via verifiable outcomes</li><li>Credit and partner workflows that consume artifacts, not raw private state</li></ul><h2 id="where-this-appears-in-the-app" tabindex="-1">Where This Appears In The App <a class="header-anchor" href="#where-this-appears-in-the-app" aria-label="Permalink to &quot;Where This Appears In The App&quot;">​</a></h2><ul><li><code>/profile</code>: trust, reputation, compliance and disclosure context</li><li><code>/agent</code> (Capital OS): privacy vault actions, controls, and orchestration</li><li><code>/trade</code> (Trade Desk): privacy level per opportunity, adapter routes, slippage simulation, execution receipts</li></ul><h2 id="core-privacy-flow" tabindex="-1">Core Privacy Flow <a class="header-anchor" href="#core-privacy-flow" aria-label="Permalink to &quot;Core Privacy Flow&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20I%5BPrivate%20inputs%5D%20--%3E%20P%5BPolicy%20and%20proof%20checks%5D%0A%20%20P%20--%3E%20E%5BExecution%20route%5D%0A%20%20E%20--%3E%20R%5BReceipt%20trail%5D%0A%20%20P%20--%3E%20D%5BOptional%20disclosure%20artifact%5D%0A%20%20R%20--%3E%20U%5BTrust%20and%20reputation%20updates%5D%0A%20%20D%20--%3E%20U">flowchart LR
  I[Private inputs] --&gt; P[Policy and proof checks]
  P --&gt; E[Execution route]
  E --&gt; R[Receipt trail]
  P --&gt; D[Optional disclosure artifact]
  R --&gt; U[Trust and reputation updates]
  D --&gt; U</pre><h2 id="representative-apis" tabindex="-1">Representative APIs <a class="header-anchor" href="#representative-apis" aria-label="Permalink to &quot;Representative APIs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/deposit/generate_commitment</code></td><td>Build privacy commitment</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/withdraw/generate_proof</code></td><td>Build withdrawal proof</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/deposit</code></td><td>Unified privacy deposit flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/withdraw</code></td><td>Unified privacy withdraw flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/compliance/profiles/{user_address}</code></td><td>Read compliance/disclosure profile</td></tr></tbody></table><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>These are technical capabilities. They are not legal, tax, or investment advice.</p><p>Next: <a href="/docs/profile-and-identity">Profile And Identity</a> | <a href="/docs/capital-os">Capital OS</a> | <a href="/docs/trade-desk">Trade Desk</a></p>`,21)])])}const f=a(o,[["render",d]]);export{u as __pageData,f as default};
